import{_ as a,C as i,o as n,c as r,j as t,a as o,E as l,ak as c}from"./chunks/framework.sV-XtlWr.js";const d="/screenshots/create-issue-modal.png",h="/screenshots/cluster-issue-chip.png",u="/screenshots/project-integration-binding.png",v=JSON.parse('{"title":"Issue tracking (Jira)","description":"","frontmatter":{"title":"Issue tracking (Jira)","lang":"en-US"},"headers":[],"relativePath":"features/issue-tracking.md","filePath":"features/issue-tracking.md","lastUpdated":1789731008000}'),g={name:"features/issue-tracking.md"};function m(p,e,f,k,b,y){const s=i("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"issue-tracking-jira",tabindex:"-1"},[o("Issue tracking (Jira) "),t("a",{class:"header-anchor",href:"#issue-tracking-jira","aria-label":'Permalink to "Issue tracking (Jira)"'},"​")],-1)),l(s,{reporter:""}),e[1]||(e[1]=c('<p>Piwi already ends an investigation with everything a ticket needs — a headline, the affected tests and their owners, the diagnosis, a validated patch, the failing locator, the verify command. <strong>Create issue</strong> turns that into a Jira issue in one click: the body is the fix plan, the issue is linked back as the cluster&#39;s <em>known issue</em>, and from then on the key travels wherever the failure appears.</p><p>It is <strong>off until an <a href="/operate/integrations.html#connecting-jira-cloud">administrator connects Jira</a></strong>; with no connection, none of the entry points appear.</p><div class="doc-screenshot"><img src="'+d+'" alt="The Create issue modal on a failure cluster: an editable title, the Jira project and issue-type fields, include toggles, and a preview of the fix-plan body"></div><h2 id="what-it-does-exactly" tabindex="-1">What it does, exactly <a class="header-anchor" href="#what-it-does-exactly" aria-label="Permalink to &quot;What it does, exactly&quot;">​</a></h2><ul><li><strong>Create issue</strong> appears on a failure cluster, on a failing execution, and on each inbox row (plus the <code>c</code> key and a <em>Create issues</em> button in the inbox bulk bar). It is the primary action while the cluster has no ticket; once one exists, the chip shows the key and status and the action becomes <em>Open in Jira</em>.</li><li>The issue <strong>body is the fix plan</strong>, rendered to Atlassian Document Format: <em>What happened</em>, <em>Most likely</em>, <em>Evidence</em>, <em>What to do</em> (patch, locator replacement, verify command, reproduce steps) and <em>Links</em> back to Piwi. Every section degrades independently.</li><li>Each issue carries the labels <code>piwi</code>, <code>piwi-cluster-&lt;id&gt;</code> and <code>piwi-fp-&lt;hash&gt;</code> and a <code>Piwi-Cluster: &lt;id&gt;</code> trailer, so a person or a JQL filter can find every Piwi-filed issue.</li><li><strong>Filing is deduped by cluster</strong> — a second click or a duplicate event is a no-op — and before creating, the modal surfaces any issue that already tracks the failure (a pinned link, a matching label, or a <em>fixed-before</em> match) and leads with <em>link it instead</em>.</li><li>Creating an issue is a <strong>durable outbox action</strong>: attempted immediately, retried with backoff if Jira is down, and recorded — <code>GET /api/integrations/actions</code> lists what Piwi wrote.</li></ul><h2 id="the-key-travels" tabindex="-1">The key travels <a class="header-anchor" href="#the-key-travels" aria-label="Permalink to &quot;The key travels&quot;">​</a></h2><p>Once a cluster has a known issue, its key follows the failure everywhere:</p><ul><li>the <strong>cluster state line</strong> and the <strong>inbox row</strong> show the key with its status color;</li><li><code>cluster.new</code>, <code>cluster.fixed</code> and <code>cluster.regressed</code> <strong>Slack and email</strong> messages name it;</li><li>the <strong>pull-request feedback</strong> comment says <em>tracked in PROJ-123</em> on each failure whose cluster has one;</li><li>the <strong>fix plan</strong> lists it under <em>Links</em>, and the <code>get_cluster</code> / <code>get_fix_plan</code> MCP tools return it.</li></ul><div class="doc-screenshot"><img src="'+h+'" alt="A failure cluster&#39;s state line showing the linked Jira issue key with an Open in Jira action"></div><h2 id="keep-the-ticket-honest" tabindex="-1">Keep the ticket honest <a class="header-anchor" href="#keep-the-ticket-honest" aria-label="Permalink to &quot;Keep the ticket honest&quot;">​</a></h2><p>Once a cluster carries a known issue, Piwi keeps the two in step. A background sync (<a href="/reference/configuration.html"><code>PIWI_INTEGRATIONS_SYNC_MINUTES</code></a>, default 15 min) reads each tracked issue back and caches its status, title and assignee — so a closed ticket stops showing as open (open clusters refresh every sweep, resolved ones daily). On top of that, per-project <strong>policies</strong> — all <strong>off by default</strong>, each a durable deduped outbox action — write back as the cluster evolves:</p><table tabindex="0"><thead><tr><th>When Piwi observes</th><th>What Piwi does</th></tr></thead><tbody><tr><td>A cluster&#39;s <strong>fix is verified</strong></td><td>Comments <em>Fix landed in run #N …</em>, and — with <em>transition on fix</em> — moves the issue.</td></tr><tr><td>A cluster <strong>regresses</strong></td><td>Comments <em>Regressed in run #N …</em>, and optionally reopens the issue.</td></tr><tr><td><strong>New occurrences</strong> on an open ticket</td><td>At most one comment a day: <em>Still failing — +N occurrences in M runs …</em>.</td></tr><tr><td>A cluster is <strong>merged</strong></td><td>With <em>comment on merge</em>, notes it on both issues; the survivor inherits the links.</td></tr><tr><td>The <strong>ticket moves to Done</strong></td><td>With <em>resolve on close</em>, resolves the cluster; otherwise its state line offers <em>Mark resolved — PROJ-123 is Done</em>.</td></tr><tr><td>The <strong>ticket is reopened</strong></td><td>With <em>reopen on ticket reopen</em>, reopens a resolved cluster with a note.</td></tr></tbody></table><p>Every comment is written in the <a href="#language">ticket&#39;s language</a>. A Jira admin can also register an optional <a href="/operate/integrations.html#registering-the-inbound-webhook">inbound webhook</a> so a close or reopen reflects immediately; it can only refresh a link, never create or transition. The failure inbox gains a <strong>Needs ticket</strong> queue — open clusters on the default branch, older than the binding&#39;s age (default 2 days), with no issue.</p><h2 id="the-project-binding" tabindex="-1">The project binding <a class="header-anchor" href="#the-project-binding" aria-label="Permalink to &quot;The project binding&quot;">​</a></h2><p>An administrator binds a project under <strong>Project → Settings → Issue tracker</strong>: the connection, Jira project and issue type, default labels and assignee, the <a href="#language">ticket language</a>, what a ticket carries, the policies above, and <strong>owner routes</strong> — mapping a cluster&#39;s owner (<code>@acme/checkout</code>, an email) to a Jira project, component, assignee and labels. The create-issue draft picks the first matching route and fills the rest from the defaults, so a team&#39;s failures reach that team&#39;s destination. The <strong>automatic-creation</strong> fields are shown greyed out: stored, but inert — Piwi does not file tickets on its own in this release.</p><div class="doc-screenshot"><img src="'+u+'" alt="The project&#39;s Issue tracker settings: connection, Jira project and issue type, labels, sync-policy switches, an owner-routes table, and the greyed-out automatic-creation fields"></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A connected <strong>Jira Cloud</strong> site — see <a href="/operate/integrations.html#connecting-jira-cloud">Operate → Integrations</a>.</li><li><strong><code>PIWI_SITE_URL</code></strong> set, so the issue body&#39;s links resolve back to the dashboard.</li><li><strong>Reporter or administrator</strong> to create or link an issue; any project member can read the key and status.</li></ul><h2 id="enable-it" tabindex="-1">Enable it <a class="header-anchor" href="#enable-it" aria-label="Permalink to &quot;Enable it&quot;">​</a></h2><p>There is nothing to switch on beyond the connection. The modal prefills the Jira project, issue type, labels and assignee from the <a href="#the-project-binding">project binding</a> when one exists, else offers pickers over the connected site; toggles choose what the body carries (diagnosis and patch on, screenshot and <a href="/features/share-links.html">share link</a> off). From an AI agent, the <a href="/features/mcp.html"><code>create_issue</code> MCP tool</a> files the same ticket.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>A ticket is written for a team, so its language is a property of its <strong>destination</strong>. It resolves from the <strong>project binding</strong>&#39;s language, else the <strong>connection</strong>&#39;s default (a French Atlassian site can default every ticket to French), else <strong>English</strong>. The create modal offers a per-issue <em>Language</em> select and the <code>create_issue</code> MCP tool takes a <code>locale</code>. <strong>English and French ship today</strong>; another language is one catalog file in <code>shared/integrations/messages/</code>.</p><p>Only the copy <strong>Piwi authors</strong> is translated — headings, fact labels, policy comments, dates and counts (via <code>Intl</code>). Your data (test titles, error text, locators, paths, the verify command, the patch) is <strong>never</strong> translated. The model&#39;s prose follows the separate <a href="/features/ai-diagnosis.html#response-language">AI response-language setting</a>, so a French ticket&#39;s <em>Most likely</em> section reads in French too. Jira&#39;s issue types, priorities and statuses are addressed by id, so a French-configured site works unchanged.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Jira Cloud only</strong> in this release (REST v3, email + API token); Server / Data Center, GitHub and GitLab Issues follow as provider files.</li><li><strong>Creation stays manual</strong> — Piwi syncs a ticket and files it on a click, but never files one on its own yet.</li><li>A ticket&#39;s body is a <strong>snapshot</strong> at creation; the policies add comments and status changes rather than editing it.</li><li>The dashboard&#39;s deterministic sentences (headline, story, clue, state line) are <strong>English templates</strong> that quote locators and Playwright terms, so they stay English even in a French ticket.</li><li>Attachments honor the <a href="/features/offline-export.html">export size budget</a>; the trace is never attached.</li></ul>',25))])}const x=a(g,[["render",m]]);export{v as __pageData,x as default};
